mapper.update:
UPDATE eval_batch
SET status      = #{status},
    report      = #{report},
    cost_stat   = #{costStat},
    finished_at = #{finishedAt}
WHERE id = #{id}

mapper.select:
SELECT id, batch_kind AS batchKind, scope, status, report, cost_stat AS costStat, created_at AS createdAt, finished_at AS finishedAt FROM eval_batch
batch_kind = #{batchKind}
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}
